import{_ as t,o,c as s,a0 as r}from"./chunks/framework.ChlVJx0I.js";const h=JSON.parse('{"title":"Resource toggles write the native settings override patterns","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0012-resource-toggles-write-native-settings-patterns.md","filePath":"adr/0012-resource-toggles-write-native-settings-patterns.md","lastUpdated":1789547600000}'),i={name:"adr/0012-resource-toggles-write-native-settings-patterns.md"};function n(a,e,d,c,l,p){return o(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="resource-toggles-write-the-native-settings-override-patterns" tabindex="-1">Resource toggles write the native settings override patterns <a class="header-anchor" href="#resource-toggles-write-the-native-settings-override-patterns" aria-label="Permalink to &quot;Resource toggles write the native settings override patterns&quot;">​</a></h1><p>The resource-toggle extension must persist enable/disable state where pi reads it before resources load, and it must stay interchangeable with pi&#39;s own <code>pi config</code> tool. We decided: the extension writes the native override patterns (<code>+path</code> force-include, <code>-path</code> force-exclude) into the <code>extensions</code>, <code>skills</code>, <code>prompts</code>, and <code>themes</code> arrays of the settings files, in global or project scope, and applies changes with an in-session reload. No private config file of its own.</p><h2 id="considered-options" tabindex="-1">Considered Options <a class="header-anchor" href="#considered-options" aria-label="Permalink to &quot;Considered Options&quot;">​</a></h2><ul><li><strong>Native settings patterns (chosen).</strong> The only storage pi consults during resource resolution, so a disabled resource is fully unloaded at load time with no hook in between. The state is visible to and writable by <code>pi config</code>, so both tools share one source of truth. A workspace-level disable of a global resource uses pi&#39;s own shadowing: a plain path plus a pattern in the project settings re-registers the resource at project scope, which wins the precedence deduplication.</li><li><strong>Private toggle file.</strong> No load-time hook reads such a file, so the extension would have to translate it into settings patterns before every resolve. That is the same write with one extra indirection, plus a second source of truth that <code>pi config</code> cannot see.</li><li><strong>Runtime suppression.</strong> An extension cannot prevent another extension&#39;s factory from running, and registered commands cannot be unregistered, so suppression would leave half of a disabled extension live.</li></ul>',4)])])}const u=t(i,[["render",n]]);export{h as __pageData,u as default};
